module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal signal for the next state of the game
    logic [255:0] next_q;

    // Combinational logic: compute one step of the toroidal Game of Life
    always_comb begin
        logic [3:0] count;
        integer     i, dr, dc;
        logic [3:0] r, c;
        logic [3:0] nr, nc;
        integer     ni;

        for (i = 0; i < 256; i = i + 1) begin
            // Row and column of the current cell (0..15)
            r = i / 16;
            c = i % 16;

            // Count live neighbours with toroidal (wrap-around) boundary
            count = 0;
            for (dr = -1; dr <= 1; dr = dr + 1) begin
                for (dc = -1; dc <= 1; dc = dc + 1) begin
                    if (dr == 0 && dc == 0) continue; // skip self

                    // Wrap-around using modulo 16
                    nr = (r + dr + 16) % 16;
                    nc = (c + dc + 16) % 16;
                    ni = nr * 16 + nc; // linear bit index

                    count = count + q[ni];
                end
            end

            // Apply Game of Life rules
            case (count)
                0, 1: next_q[i] = 0;            // Rule (1): 0-1 neighbour -> die
                2:    next_q[i] = q[i];          // Rule (2): 2 neighbours -> stay same
                3:    next_q[i] = 1;             // Rule (3): 3 neighbours -> become alive
                default: next_q[i] = 0;          // Rule (4): 4+ neighbours -> die
            endcase
        end
    end

    // Sequential logic: clocked flip-flop with synchronous load
    always_ff @(posedge clk) begin
        if (load)
            q <= data;   // Load initial state (active high synchronous)
        else
            q <= next_q; // Advance one generation
    end

